import React, { useState, useCallback, useEffect, useMemo, useRef } from 'react';
import Layout from '@theme/Layout';
import Head from '@docusaurus/Head';
import { Highlight, type Token } from 'prism-react-renderer';
import { usePrismTheme } from '@docusaurus/theme-common';
import styles from './playground.module.css';
// Regenerated by backend/deploy.sh on every binary deploy via
// `iec_checker --dump-config`. Do not edit by hand.
import defaultConfigData from '@site/src/data/iec-checker-default-config.json';

// iec-checker JSON diagnostic format
interface Diagnostic {
  linenr: number;
  column: number;
  file: string;
  id: string;
  msg: string;
  type: string[];
  // Set on the backend's hints (id 'Hint'); `report` is false when the input, not the parser, is at fault.
  kind?: string;
  report?: boolean;
}

const API_BASE =
  typeof window !== 'undefined' && window.location.hostname === 'localhost'
    ? 'http://localhost:8080'
    : 'https://iec-checker.nowarp.io';

interface VersionInfo {
  version: string;
  commit: string;
  commit_short: string;
  commit_date: string;
}

const DEFAULT_CONFIG_JSON = JSON.stringify(defaultConfigData, null, 2);

const EXAMPLE_PROGRAMS: Record<string, string> = {
  '': '', // placeholder for "Select example..."
  'Float equality (CP8)': `PROGRAM main
VAR
  x : REAL := 1.0;
  y : REAL := 1.0;
END_VAR
  IF x = y THEN
    x := x + 0.1;
  END_IF;
END_PROGRAM
`,
  'Uninitialized variable (CP3)': `FUNCTION_BLOCK FB_Example
VAR
  counter : INT;
  result  : INT;
END_VAR
  result := counter + 1;
END_FUNCTION_BLOCK
`,
  'Missing ELSE (L17)': `PROGRAM main
VAR
  mode : INT := 0;
  output : BOOL;
END_VAR
  IF mode = 1 THEN
    output := TRUE;
  END_IF;
END_PROGRAM
`,
  'Duty pump selection': `FUNCTION_BLOCK FB_DutyPump
VAR_INPUT
  abAvailable : ARRAY[1..4] OF BOOL := [4(TRUE)];
  fPressure   : REAL := 0.0;
END_VAR
VAR_OUTPUT
  abRun   : ARRAY[1..4] OF BOOL := [4(FALSE)];
  nDuty   : INT := 1;
  bDryRun : BOOL := FALSE;
END_VAR
VAR
  i      : INT := 1;
  tonRun : TON;
END_VAR
FOR i := 1 TO 4 DO
  IF abAvailable[i] THEN
    EXIT;
  END_IF;
END_FOR;
nDuty := i;
abRun[nDuty] := NOT bDryRun;
tonRun(IN := abRun[nDuty], PT := T#60S);
IF tonRun.ET = T#5S AND fPressure < 1.5 THEN
  bDryRun := TRUE;
END_IF;
END_FUNCTION_BLOCK
`,
  'Analog input scaling': `FUNCTION_BLOCK FB_AnalogIn
VAR_INPUT
  iRaw      : INT := 0;
  fDeadband : REAL := 0.5;
END_VAR
VAR_OUTPUT
  fValue  : REAL := 0.0;
  bReport : BOOL := FALSE;
END_VAR
VAR
  fRaw      : REAL := 0.0;
  fReported : REAL := 0.0;
END_VAR
(* 4..20 mA = 5530..27648 counts -> 0..100 % *)
fRaw := iRaw;
fValue := (fRaw - 5530.0) * 100.0 / 22118.0;
bReport := fValue <> fReported;
IF bReport THEN
  fReported := fValue;
END_IF;
END_FUNCTION_BLOCK
`,
  'Lift I/O mapping': `PROGRAM PRG_IoMap
VAR
  diEStopOk    AT %IX0.0 : BOOL;
  aiLiftPos    AT %IW64  : INT;
  diEncoderCnt AT %ID66  : DINT;
  wVfdStatus   AT %IW68  : WORD;
  doBrakeRel   AT %QX0.0 : BOOL;
END_VAR
VAR_EXTERNAL
  gstIn  : ST_LiftInputs;
  gstOut : ST_LiftOutputs;
END_VAR
gstIn.fPosMm    := INT_TO_REAL(aiLiftPos) / 10.0;
gstIn.nEncoder  := diEncoderCnt;
gstIn.bVfdFault := wVfdStatus.3;
doBrakeRel := gstOut.bBrakeRelease AND diEStopOk;
%QX0.5 := gstOut.bWarningLamp;
END_PROGRAM
`,
};

// Known detector IDs that have docs pages
const DETECTOR_DOC_IDS = new Set([
  'OutOfBounds', 'UnusedVariable', 'UncalledInstance',
  'PLCOPEN-CP1', 'PLCOPEN-CP2', 'PLCOPEN-CP3', 'PLCOPEN-CP4',
  'PLCOPEN-CP6', 'PLCOPEN-CP8', 'PLCOPEN-CP9', 'PLCOPEN-CP13',
  'PLCOPEN-CP17', 'PLCOPEN-CP20', 'PLCOPEN-CP25', 'PLCOPEN-CP28', 'PLCOPEN-L10', 'PLCOPEN-L17',
  'PLCOPEN-N3',
]);

function detectorDocUrl(id: string): string | null {
  return DETECTOR_DOC_IDS.has(id) ? `/docs/detectors/${id}` : null;
}

function StHighlight({ code }: { code: string }): React.ReactElement {
  const p = usePrismTheme();
  return (
    <Highlight code={code} language="iecst" theme={p}>
      {({ tokens, getTokenProps }) => (
        <pre className={styles.editorHighlight} style={{ color: p.plain.color }} aria-hidden="true">
          {tokens.map((l, i) => (
            <React.Fragment key={i}>
              {i > 0 && '\n'}
              {l.map((t: Token, j) =>
                t.empty ? null : <span key={j} {...getTokenProps({ token: t })} />,
              )}
            </React.Fragment>
          ))}
          {/* HACK: a trailing newline adds no line box to a <pre>, unlike the textarea */}
          {' '}
        </pre>
      )}
    </Highlight>
  );
}

export default function Playground(): React.ReactElement {
  const [code, setCode] = useState('');
  const [diagnostics, setDiagnostics] = useState<Diagnostic[] | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const [showInfo, setShowInfo] = useState(() => {
    if (typeof document === 'undefined') return false;
    const seen = document.cookie.split('; ').some((c) => c === 'playground_info_seen=1');
    return !seen;
  });
  const [showConfig, setShowConfig] = useState(false);
  const [configCopied, setConfigCopied] = useState(false);
  const [versionInfo, setVersionInfo] = useState<VersionInfo | null>(null);
  const textareaRef = useRef<HTMLTextAreaElement | null>(null);
  const scrollRef = useRef<HTMLDivElement | null>(null);

  const lineCount = useMemo(() => {
    // Always show at least one line number, and add one for a trailing newline.
    if (!code) return 1;
    const n = code.split('\n').length;
    return n;
  }, [code]);

  const lineNumbers = useMemo(
    () => Array.from({ length: lineCount }, (_, i) => i + 1).join('\n'),
    [lineCount],
  );

  const goToLocation = useCallback(
    (line: number) => {
      const ta = textareaRef.current;
      const sc = scrollRef.current;
      if (!ta || !sc) return;
      const lines = code.split('\n');
      if (line < 1 || line > lines.length) return;
      let start = 0;
      for (let i = 0; i < line - 1; i++) start += lines[i].length + 1;
      const end = start + lines[line - 1].length;
      ta.focus({ preventScroll: true });
      ta.setSelectionRange(start, end);
      const cs = window.getComputedStyle(ta);
      const lh = parseFloat(cs.lineHeight) || parseFloat(cs.fontSize) * 1.5 || 18;
      sc.scrollTop = Math.max(
        0,
        parseFloat(cs.paddingTop) + (line - 1) * lh - sc.clientHeight / 2 + lh / 2,
      );
      sc.scrollLeft = 0;
    },
    [code],
  );

  const isValidLocation = useCallback(
    (line: number, col: number) => {
      if (!Number.isFinite(line) || !Number.isFinite(col)) return false;
      if (line < 1 || col < 1) return false;
      const total = code ? code.split('\n').length : 0;
      return line <= total;
    },
    [code],
  );

  const renderMessageWithLocations = useCallback(
    (msg: string): React.ReactNode => {
      const re = /(?<![\w.])(\d+):(\d+)(?![\w.])/g;
      const out: React.ReactNode[] = [];
      let last = 0;
      let m: RegExpExecArray | null;
      let key = 0;
      while ((m = re.exec(msg)) !== null) {
        const line = parseInt(m[1], 10);
        const col = parseInt(m[2], 10);
        if (!isValidLocation(line, col)) continue;
        if (m.index > last) out.push(msg.slice(last, m.index));
        out.push(
          <button
            key={`loc-${key++}`}
            type="button"
            className={styles.locationLink}
            onClick={() => goToLocation(line)}
            title={`Jump to line ${line}`}
          >
            {m[0]}
          </button>,
        );
        last = m.index + m[0].length;
      }
      if (last < msg.length) out.push(msg.slice(last));
      return out.length > 0 ? out : msg;
    },
    [goToLocation, isValidLocation],
  );

  const copyConfig = useCallback(() => {
    if (typeof navigator === 'undefined' || !navigator.clipboard) return;
    navigator.clipboard.writeText(DEFAULT_CONFIG_JSON).then(() => {
      setConfigCopied(true);
      setTimeout(() => setConfigCopied(false), 1500);
    });
  }, []);

  useEffect(() => {
    fetch(`${API_BASE}/api/version`)
      .then((r) => (r.ok ? r.json() : null))
      .then((data) => data && setVersionInfo(data))
      .catch(() => {});
  }, []);

  const runCheck = useCallback(async () => {
    if (!code.trim()) return;
    setLoading(true);
    setError(null);
    setDiagnostics(null);

    try {
      const resp = await fetch(`${API_BASE}/api/check`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ code }),
      });

      if (!resp.ok) {
        const text = await resp.text();
        throw new Error(`Server returned ${resp.status}: ${text}`);
      }

      const data: Diagnostic[] = await resp.json();
      setDiagnostics(data);
    } catch (err: unknown) {
      setError(err instanceof Error ? err.message : String(err));
    } finally {
      setLoading(false);
    }
  }, [code]);

  const handleKeyDown = useCallback(
    (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
      // Ctrl/Cmd + Enter to run
      if ((e.ctrlKey || e.metaKey) && e.key === 'Enter') {
        e.preventDefault();
        runCheck();
        return;
      }
      // Tab inserts spaces
      if (e.key === 'Tab') {
        e.preventDefault();
        const textarea = e.currentTarget;
        const start = textarea.selectionStart;
        const end = textarea.selectionEnd;
        const newValue = code.substring(0, start) + '  ' + code.substring(end);
        setCode(newValue);
        requestAnimationFrame(() => {
          textarea.selectionStart = textarea.selectionEnd = start + 2;
        });
      }
    },
    [code, runCheck],
  );

  const handleExampleChange = useCallback(
    (e: React.ChangeEvent<HTMLSelectElement>) => {
      const program = EXAMPLE_PROGRAMS[e.target.value];
      if (program) {
        setCode(program);
        setDiagnostics(null);
        setError(null);
      }
    },
    [],
  );

  return (
    <Layout description="Try iec-checker online" noFooter>
      <Head>
        <title>Try Online — iec-checker</title>
      </Head>

      <div className={styles.playgroundContainer}>
        {/* Toolbar */}
        <div className={styles.toolbar}>
          <div className={styles.toolbarLeft}>
            <button
              className={styles.runButton}
              onClick={runCheck}
              disabled={loading || !code.trim()}
            >
              {loading ? (
                <>
                  <i className="fa-solid fa-spinner fa-spin" aria-hidden="true" />
                  Running…
                </>
              ) : (
                <>
                  <i className="fa-solid fa-play" aria-hidden="true" />
                  Run
                </>
              )}
            </button>
            <select
              className={styles.exampleSelect}
              onChange={handleExampleChange}
              defaultValue=""
            >
              <option value="" disabled>
                Load example…
              </option>
              {Object.keys(EXAMPLE_PROGRAMS)
                .filter(Boolean)
                .map((name) => (
                  <option key={name} value={name}>
                    {name}
                  </option>
                ))}
            </select>
          </div>
          <div className={styles.toolbarRight}>
            {versionInfo && (
              <span className={styles.versionLabel}>
                v{versionInfo.version} (
                <a
                  href={`https://github.com/iec-checker/iec-checker/commit/${versionInfo.commit}`}
                  target="_blank"
                  rel="noopener noreferrer"
                >
                  {versionInfo.commit_short}
                </a>
                , {versionInfo.commit_date.split(' ')[0]})
              </span>
            )}
            <kbd>Ctrl</kbd>+<kbd>Enter</kbd> to run
            <div className={styles.infoWrapper}>
              <button
                className={styles.infoButton}
                onClick={() => setShowConfig((v) => !v)}
                aria-label="Default config"
                title="Default config"
              >
                <i className="fa-solid fa-gear" aria-hidden="true" />
              </button>
              {showConfig && (
                <>
                  <div
                    className={styles.infoBackdrop}
                    onClick={() => setShowConfig(false)}
                  />
                  <div
                    className={`${styles.infoPopup} ${styles.configPopup}`}
                    onClick={(e) => e.stopPropagation()}
                  >
                    <div className={styles.configHeader}>
                      <strong>Default configuration</strong>
                      <button
                        className={styles.configCopyButton}
                        onClick={copyConfig}
                        aria-label="Copy config"
                      >
                        <i
                          className={`fa-solid ${configCopied ? 'fa-check' : 'fa-copy'}`}
                          aria-hidden="true"
                        />
                        {configCopied ? 'Copied' : 'Copy'}
                      </button>
                    </div>
                    <p className={styles.configHint}>
                      The playground runs <code>iec_checker</code> with this
                      effective config. Generate a local copy via{' '}
                      <code>iec_checker --generate-config</code>.
                    </p>
                    <pre className={styles.configPre}>{DEFAULT_CONFIG_JSON}</pre>
                  </div>
                </>
              )}
            </div>
            <div className={styles.infoWrapper}>
              <button
                className={styles.infoButton}
                onClick={() => setShowInfo((v) => !v)}
                aria-label="Info"
              >
                ?
              </button>
              {showInfo && (
                <>
                  <div
                    className={styles.infoBackdrop}
                    onClick={() => {
                      setShowInfo(false);
                      document.cookie = 'playground_info_seen=1; path=/; SameSite=Lax';
                    }}
                  />
                  <div className={styles.infoPopup} onClick={(e) => e.stopPropagation()}>
                    <ul className={styles.infoList}>
                      <li>
                        This is a <strong>demonstration site</strong> for reference
                        only and cannot be used for code verification.
                      </li>
                      <li>
                        <strong>DO NOT</strong> upload safety-critical components!
                        The input code is saved on the server during analysis.
                        The server&apos;s security is not audited and will never be.
                      </li>
                      <li>
                        If you find any issues, please report them at{' '}
                        <a
                          href="https://github.com/iec-checker/iec-checker/issues"
                          target="_blank"
                          rel="noopener noreferrer"
                        >
                          GitHub Issues
                        </a>
                        .
                      </li>
                    </ul>
                  </div>
                </>
              )}
            </div>
          </div>
        </div>

        {/* Split panels */}
        <div className={styles.panels}>
          {/* Editor */}
          <div className={styles.editorPanel}>
            <div className={styles.panelHeader}>Structured Text</div>
            <div ref={scrollRef} className={styles.editorWrap}>
              <div className={styles.editorInner}>
                <div className={styles.lineNumbers} aria-hidden="true">
                  {lineNumbers}
                </div>
                <div className={styles.editorCode}>
                  <StHighlight code={code} />
                  <textarea
                    ref={textareaRef}
                    className={styles.editorTextarea}
                    value={code}
                    onChange={(e) => setCode(e.target.value)}
                    onKeyDown={handleKeyDown}
                    placeholder="Paste your IEC 61131-3 Structured Text program here…"
                    spellCheck={false}
                    autoCapitalize="off"
                    autoCorrect="off"
                    wrap="off"
                    rows={1}
                  />
                </div>
              </div>
            </div>
          </div>

          {/* Results */}
          <div className={styles.resultsPanel}>
            <div className={styles.panelHeader}>Diagnostics</div>
            <div className={styles.resultsBody}>
              {error && (
                <div className={styles.errorBanner}>
                  {error}
                  <br />
                  If this issue persists, please reach out to{' '}
                  <a href="mailto:jubnzv@gmail.com">jubnzv@gmail.com</a>.
                </div>
              )}

              {!diagnostics && !error && (
                <div className={styles.emptyState}>
                  <div className={styles.emptyStateIcon}>
                    <i className="fa-solid fa-terminal" aria-hidden="true" />
                  </div>
                  <span>Write or paste a program, then hit Run.</span>
                </div>
              )}

              {diagnostics && diagnostics.length === 0 && (
                <div className={styles.successBanner}>
                  <i className="fa-solid fa-circle-check" aria-hidden="true" />
                  No issues found. Your code looks clean.
                </div>
              )}

              {diagnostics && diagnostics.length > 0 && (() => {
                const hasParseErrors = diagnostics.some(
                  (d) => d.id === 'ParserError' || d.id === 'LexingError',
                );
                const onlyParseErrors = hasParseErrors && diagnostics.every(
                  (d) => d.id === 'ParserError' || d.id === 'LexingError' || d.id === 'Hint',
                );
                const inputAtFault = diagnostics.some((d) => d.id === 'Hint' && d.report === false);
                return (
                  <>
                    <ul className={styles.diagnosticList}>
                      {diagnostics.map((d, i) => {
                        const docUrl = detectorDocUrl(d.id);
                        const isError = d.id === 'ParserError' || d.id === 'LexingError';
                        const isHint = d.id === 'Hint';
                        const msg = d.msg || (isError ? 'Syntax error' : 'Unknown issue');
                        const itemClass = isError ? styles.diagnosticError : isHint ? styles.diagnosticHint : '';
                        const idClass = isError ? styles.diagnosticIdError : isHint ? styles.diagnosticIdHint : styles.diagnosticId;
                        return (
                          <li key={i} className={`${styles.diagnosticItem} ${itemClass}`}>
                            {isValidLocation(d.linenr, d.column) ? (
                              <button
                                type="button"
                                className={`${styles.diagnosticLocation} ${styles.locationLink}`}
                                onClick={() => goToLocation(d.linenr)}
                                title={`Jump to line ${d.linenr}`}
                              >
                                {d.linenr}:{d.column}
                              </button>
                            ) : (
                              <span className={styles.diagnosticLocation}>
                                {d.linenr}:{d.column}
                              </span>
                            )}
                            <span className={idClass}>
                              {isHint && <i className="fa-solid fa-lightbulb" aria-hidden="true" />}{' '}
                              {docUrl ? (
                                <a
                                  href={docUrl}
                                  target="_blank"
                                  rel="noopener noreferrer"
                                  className={styles.diagnosticIdLink}
                                >
                                  {d.id}
                                </a>
                              ) : (
                                d.id
                              )}
                            </span>
                            <span className={styles.diagnosticMsg}>{renderMessageWithLocations(msg)}</span>
                          </li>
                        );
                      })}
                    </ul>
                    {hasParseErrors && !inputAtFault && (
                      <a
                        className={styles.reportLink}
                        href={`https://github.com/iec-checker/iec-checker/issues/new?${new URLSearchParams({
                          title: 'Parser error from Try Online',
                          labels: 'bug',
                          body: [
                            '### Environment\n',
                            '- **PLC IDE**: <!-- e.g. CODESYS 3.5 SP19, TIA Portal V18, Beckhoff TwinCAT 3.1 -->',
                            '- **iec-checker version**: ' + (versionInfo ? `${versionInfo.version} (${versionInfo.commit_short}, ${versionInfo.commit_date.split(' ')[0]})` : 'unknown'),
                            '- **Platform**: Try Online\n',
                            '### Source code\n',
                            '```iecst',
                            code.length > 150 ? '<!-- please paste the program here -->' : code,
                            '```\n',
                            '### Current behavior\n',
                            '```',
                            diagnostics.filter((d) => d.id === 'ParserError' || d.id === 'LexingError').map((d) => `${d.linenr}:${d.column} ${d.id}: ${d.msg || 'Syntax error'}`).join('\n'),
                            '```\n',
                            '### Expected behavior\n',
                            '<!-- What you expected to happen instead. -->',
                          ].join('\n'),
                        }).toString()}`}
                        target="_blank"
                        rel="noopener noreferrer"
                      >
                        <i className="fa-solid fa-bug" aria-hidden="true" />{' '}
                        {onlyParseErrors
                          ? 'Using a vendor ST extension we don\u2019t know yet? Open an issue and help us add support.'
                          : 'Looks like a bug? Report this issue'}
                      </a>
                    )}
                  </>
                );
              })()}
            </div>
          </div>
        </div>
      </div>
    </Layout>
  );
}
